insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_10_v1'
from (values
('128.34.c.1.A',3,'In a respectful class discussion, an English learner shows active listening by:','["nodding, waiting for a turn and responding to the speaker''s point", "interrupting with a new topic", "speaking over others", "looking at a phone"]'::jsonb,0,'Active listening includes appropriate response.','original'),
('128.34.c.1.A',3,'A learner wants to disagree politely in English. Which phrase works best?','["That is wrong.", "I see your point, but I have a different view.", "Stop talking.", "You don''t understand."]'::jsonb,1,'Polite disagreement acknowledges the other speaker.','original'),
('128.34.c.1.B',3,'Sharing prior knowledge with peers helps communication because it:','["slows listening", "removes questions", "gives everyone common background for the topic", "hides the topic"]'::jsonb,2,'Shared knowledge supports understanding.','original'),
('128.34.c.1.B',3,'Before a group project on the water cycle, a learner explains what they already know about rain in their home country. This is:','["reading aloud", "avoiding the task", "taking attendance", "sharing prior knowledge"]'::jsonb,3,'Prior knowledge links new topics to experience.','original'),
('128.34.c.1.C',3,'Complex oral instructions include several steps. The best way to follow them is to:','["restate the steps and ask about any step that is unclear", "guess the steps", "ignore the last step", "wait without asking"]'::jsonb,0,'Restating confirms understanding.','original'),
('128.34.c.1.C',3,'Which set of oral directions is complex?','["Close the book.", "Open the file, copy the table, change the heading, and then save it under a new name.", "Open the door.", "Sit down."]'::jsonb,1,'Complex directions include several actions in order.','original'),
('128.34.c.1.D',3,'A formal presentation to the school board should use:','["slang and jokes", "whispering", "formal language and a respectful tone", "text abbreviations"]'::jsonb,2,'Language should match audience and purpose.','original'),
('128.34.c.1.D',3,'Technical language is most appropriate when presenting to:','["young children with no background", "a friend at lunch", "a stranger in a store", "experts who know the field"]'::jsonb,3,'Technical terms suit informed audiences.','original'),
('128.34.c.1.E',3,'Building on the ideas of others in a group means:','["adding relevant information to what a teammate said", "repeating your own idea only", "changing the subject", "ending the talk"]'::jsonb,0,'Collaboration builds on contributions.','original'),
('128.34.c.1.E',3,'A good group member contributes relevant information by:','["staying silent", "staying on topic and offering useful facts", "telling unrelated stories", "arguing for fun"]'::jsonb,1,'Relevant contributions help the group.','original'),
('128.34.c.1.F',3,'Social communication in English includes:','["spelling lists", "only formal essays", "greetings, thanks, apologies and polite requests", "silent reading"]'::jsonb,2,'Social language is used in daily interaction.','original'),
('128.34.c.1.F',3,'A learner asks a teacher for help at the right time and in the right way. This shows:','["unclear language", "random language", "silent language", "contextualized, purposeful oral language"]'::jsonb,3,'Language use matches the situation.','original'),
('128.34.c.1.G',3,'A social interview might ask a new classmate:','["What do you like to do on weekends?", "When was the treaty signed?", "How many chapters are in the book?", "What is the capital of Peru?"]'::jsonb,0,'Social interviews ask personal, friendly questions.','original'),
('128.34.c.1.G',3,'An informative interview with a nurse for a career project should include:','["jokes only", "questions about education, daily tasks and challenges", "questions about celebrities", "no questions"]'::jsonb,1,'Informative interviews gather facts.','original'),
('128.34.c.10.A',3,'A news editorial calls on readers to vote. The author''s purpose is to:','["entertain with a fable", "explain a recipe", "persuade the audience to act", "describe a dream"]'::jsonb,2,'A call to vote is persuasive.','original'),
('128.34.c.10.A',3,'To identify an author''s audience, a reader looks at:','["the font only", "the paper color", "the page number", "the topic, vocabulary and tone"]'::jsonb,3,'These clues reveal who the text is for.','original'),
('128.34.c.10.B',3,'A text that explains a process step by step uses which structure?','["sequential order", "compare and contrast", "cause and effect", "problem and solution"]'::jsonb,0,'Steps follow an order.','original'),
('128.34.c.10.B',3,'An author uses cause-and-effect structure to:','["tell a joke", "show how one event leads to another", "describe only the setting", "list unrelated facts"]'::jsonb,1,'It explains relationships.','original'),
('128.34.c.10.C',3,'Bullets, headings and a table in a manual help the reader by:','["removing details", "lengthening the text", "organizing information so it is easy to find", "hiding steps"]'::jsonb,2,'Print features aid navigation.','original'),
('128.34.c.10.D',3,'Choosing precise verbs such as ''sprinted'' instead of ''went'' helps an author:','["avoid detail", "lengthen sentences", "hide meaning", "create a clear, vivid image"]'::jsonb,3,'Precise language achieves specific effects.','original'),
('128.34.c.10.D',3,'Figurative language like ''a sea of faces'' allows an author to:','["compare to create a strong image", "cite a source", "list a rule", "state a statistic"]'::jsonb,0,'Figurative language creates meaning beyond literal words.','original'),
('128.34.c.10.E',4,'An oxymoron, such as ''deafening silence'', combines:','["identical terms", "contradictory terms to create an effect", "two rhymes", "two citations"]'::jsonb,1,'Oxymorons pair opposites.','original'),
('128.34.c.10.E',4,'Irony in a story occurs when:','["everything happens as planned", "the setting never changes", "the result is the opposite of what was expected", "the narrator is silent"]'::jsonb,2,'Irony relies on contrast.','original'),
('128.34.c.10.F',4,'Long, flowing sentences with soft words tend to create a mood that is:','["tense", "angry", "comic", "calm and reflective"]'::jsonb,3,'Syntax and diction affect mood.','original'),
('128.34.c.10.F',4,'An author''s diction is:','["the choice of words", "the number of pages", "the font", "the margins"]'::jsonb,0,'Diction means word choice.','original'),
('128.34.c.10.G',4,'An allusion is:','["a type of rhyme", "a reference to a well-known person, event or work", "a heading", "a footnote"]'::jsonb,1,'Allusions draw on shared knowledge.','original'),
('128.34.c.10.G',4,'Repetition in a speech, such as repeating ''we will not give up'', is used to:','["end the talk", "cite a source", "emphasize a key idea", "confuse listeners"]'::jsonb,2,'Repetition reinforces.','original'),
('128.34.c.10.H',4,'Understatement means:','["repeating", "exaggerating", "rhyming", "describing something as less important than it is"]'::jsonb,3,'Understatement minimizes for effect.','original'),
('128.34.c.10.H',4,'Overstatement, also called hyperbole, is:','["deliberate exaggeration", "a quotation", "a citation", "a calm description"]'::jsonb,0,'Hyperbole exaggerates for effect.','original'),
('128.34.c.11.A',3,'Before writing an essay, a learner can generate ideas by:','["grading peers", "brainstorming, freewriting or using a graphic organizer", "printing the final copy", "skipping planning"]'::jsonb,1,'Prewriting generates ideas.','original'),
('128.34.c.11.A',3,'Planning for a particular audience means deciding:','["the font size only", "the page count only", "what language and details will suit the readers", "the paper color"]'::jsonb,2,'Audience shapes content and style.','original'),
('128.34.c.11.B.i',3,'An organizing structure for a persuasive essay might be:','["rhyme, rhythm, refrain", "setting, cast, props", "title, index, glossary", "claim, reasons, evidence, counterargument, conclusion"]'::jsonb,3,'Structure should fit the genre.','original'),
('128.34.c.11.B.i',3,'A thesis statement should appear:','["in the introduction", "in the footnotes", "on the cover", "in the bibliography"]'::jsonb,0,'The thesis opens the essay.','original'),
('128.34.c.11.B.ii',3,'Which detail best develops an idea about the benefits of exercise?','["Some like sports.", "Studies show that 30 minutes of walking a day can lower stress.", "People move.", "Exercise is good."]'::jsonb,1,'Specific evidence adds depth.','original'),
('128.34.c.11.B.ii',3,'Examples in an essay are used to:','["replace the thesis", "end the paper", "make general ideas concrete", "fill the page"]'::jsonb,2,'Examples illustrate ideas.','original'),
('128.34.c.11.C',3,'Revising for diction means:','["changing margins", "printing again", "fixing only spelling", "choosing more exact words"]'::jsonb,3,'Diction is word choice.','original'),
('128.34.c.11.C',3,'A reader can improve organization during revision by:','["moving paragraphs so ideas follow a logical order", "deleting the thesis", "removing evidence", "adding errors"]'::jsonb,0,'Organization is a key revision target.','original'),
('128.34.c.11.D.i',3,'A comma splice is:','["a list", "two independent clauses joined with only a comma", "a title", "a fragment"]'::jsonb,1,'Splices need stronger punctuation or a conjunction.','original'),
('128.34.c.11.D.ii',3,'Which sentence keeps a consistent tense?','["She study English and passing the test.", "She studies English and passed the test.", "She studied English and passed the test.", "She studied English and passes the test."]'::jsonb,2,'Both verbs are past tense.','original'),
('128.34.c.11.D.iii',3,'Choose the correct verb: ''Neither the teacher nor the students ___ ready.''','["is", "was", "am", "were"]'::jsonb,3,'The verb agrees with the nearer subject, students.','original'),
('128.34.c.11.D.iv',3,'Which pronoun completes the sentence? ''Each of the boys brought ___ jacket.''','["his", "its", "our", "their"]'::jsonb,0,'Each is singular.','original'),
('128.34.c.11.D.iv',3,'In ''Maria lost her backpack,'' the pronoun her refers back to:','["the article", "the person named at the start", "the object lost", "the verb"]'::jsonb,1,'The antecedent is the noun a pronoun replaces.','original'),
('128.34.c.11.D.v',3,'Which phrase shows possession correctly?','["the students desk''s", "the studentses desks", "the students'' desks", "the student''s'' desks"]'::jsonb,2,'Plural possessive adds an apostrophe after the s.','original'),
('128.34.c.11.D.vi',3,'Which word completes the sentence? ''We will go ___ the store later.''','["two", "too", "tow", "to"]'::jsonb,3,'To is the preposition.','original'),
('128.34.c.11.D.vi',3,'Which homonym completes the sentence? ''I can''t ___ the noise.''','["bear", "beer", "bier", "bare"]'::jsonb,0,'Bear means to tolerate.','original'),
('128.34.c.11.D.vii',3,'Which of these should always be capitalized in English?','["directions like north in a sentence", "the days of the week", "common nouns", "the seasons"]'::jsonb,1,'Days of the week are proper nouns.','original'),
('128.34.c.11.D.vii',3,'Which word should be capitalized in ''the principal said we met at lincoln high school''?','["only principal", "only said", "all of: The, Lincoln, High and School", "none"]'::jsonb,2,'Sentence starts and the proper name are capitalized.','original'),
('128.34.c.11.D.viii',3,'Which sentence uses a dash to set off a phrase correctly?','["My cousin a talented artist — painted the mural.", "My — cousin a talented artist painted the mural.", "My cousin a talented — artist painted the mural.", "My cousin — a talented artist — painted the mural."]'::jsonb,3,'Dashes frame the interrupting phrase.','original'),
('128.34.c.11.D.ix',3,'The standard abbreviation for ''Doctor'' before a name is:','["Dr.", "Dctr", "Dr", "Doc"]'::jsonb,0,'Dr. with a period is standard.','original'),
('128.34.c.11.E',3,'Combining ''The dog barked. The dog was loud.'' into one sentence could produce:','["The dog loud barked.", "The dog barked loudly.", "Barked dog the.", "The dog barked. Loud."]'::jsonb,1,'Sentence combining removes repetition.','original'),
('128.34.c.11.E',3,'Sentence-combining techniques include:','["removing verbs", "deleting punctuation", "using conjunctions, relative clauses and participial phrases", "splitting nouns"]'::jsonb,2,'These techniques create varied structures.','original'),
('128.34.c.11.F',3,'A writer''s voice is:','["the font", "the margins", "the page count", "the personality that comes through in the writing"]'::jsonb,3,'Voice is individuality in style.','original'),
('128.34.c.11.F',3,'A writer can develop voice by:','["choosing distinctive words and a consistent tone", "avoiding opinions", "using only clichés", "copying others"]'::jsonb,0,'Word choice and tone create voice.','original'),
('128.34.c.11.G',2,'Publishing writing for an appropriate audience means:','["deleting the draft", "sharing a final polished version with real readers", "keeping it hidden", "leaving it unfinished"]'::jsonb,1,'Publishing completes the writing process.','original'),
('128.34.c.11.G',2,'A learner could publish a personal essay by:','["burying it in a file", "tearing it up", "posting it on the class blog", "leaving it blank"]'::jsonb,2,'Publishing shares work.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_10_v1'
from (values
('128.34.c.12.A',3,'A poem that uses vivid images and a strong speaker is an example of:','["technical text", "report", "manual", "literary text"]'::jsonb,3,'Poetry is literary.','original'),
('128.34.c.12.A',3,'In fiction, a writer builds characters by:','["showing actions, dialogue and thoughts", "listing statistics", "using footnotes", "citing sources"]'::jsonb,0,'Characterization develops people in stories.','original'),
('128.34.c.12.B',3,'An explanatory essay should:','["argue for a vote", "explain a topic clearly with facts and examples", "record a dream", "tell a fable"]'::jsonb,1,'Explanatory writing informs.','original'),
('128.34.c.12.B',3,'A personal essay differs from a report because it:','["lists only data", "uses no voice", "reflects the writer''s experience and insight", "has no thesis"]'::jsonb,2,'Personal essays combine story and reflection.','original'),
('128.34.c.12.C',3,'An argumentative text must include:','["only a story", "only jokes", "only feelings", "a claim supported by reasons and evidence"]'::jsonb,3,'Arguments need support.','original'),
('128.34.c.12.C',3,'Which sentence is the strongest claim for an argument?','["Our school should add a later start time to improve student health.", "Schools start in the morning.", "Sleep is important to people.", "Some students are tired."]'::jsonb,0,'A clear arguable claim is specific.','original'),
('128.34.c.12.D',3,'A professional email to an employer should begin with:','["slang", "a polite greeting and a clear purpose", "emojis only", "a joke"]'::jsonb,1,'Professional correspondence is formal.','original'),
('128.34.c.12.D',3,'A friendly letter differs from a business letter because it:','["needs legal terms", "uses no closing", "uses a warmer, more informal tone", "has no greeting"]'::jsonb,2,'Friendly letters are personal.','original'),
('128.34.c.13.A',3,'Which question is suitable for formal inquiry?','["Do you like apps?", "What is a phone?", "Who is online?", "How has social media changed how teenagers communicate?"]'::jsonb,3,'Formal inquiry questions are open and researchable.','original'),
('128.34.c.13.A',3,'Informal inquiry questions are:','["quick, everyday questions for exploring a topic", "only yes/no tests", "bibliographies", "strict research plans"]'::jsonb,0,'Informal inquiry is exploratory.','original'),
('128.34.c.13.B',3,'Critiquing the research process means:','["ignoring problems", "reviewing each step and changing what is not working", "copying sources", "stopping research"]'::jsonb,1,'Self-assessment improves research.','original'),
('128.34.c.13.B',3,'A researcher finds that her sources are too general. She should:','["guess", "quit", "search for more specific, relevant sources", "keep the same sources"]'::jsonb,2,'Adjust to improve quality.','original'),
('128.34.c.13.C',3,'A revised research plan may need new:','["titles", "colors", "fonts", "questions, sources or deadlines"]'::jsonb,3,'Plans adapt as needed.','original'),
('128.34.c.13.C',3,'Developing a plan involves:','["deciding what to research and how to find it", "buying books", "choosing a font", "skipping steps"]'::jsonb,0,'Planning organizes inquiry.','original'),
('128.34.c.13.D',3,'If the main question is too broad, the researcher should:','["delete it", "narrow it to refocus the plan", "ignore it", "widen it more"]'::jsonb,1,'Refocusing keeps research manageable.','original'),
('128.34.c.13.D',3,'Modifying the major research question may be needed when:','["the topic is chosen", "the title is typed", "early research shows a different focus is more useful", "the research is complete"]'::jsonb,2,'Questions evolve.','original'),
('128.34.c.13.E',3,'Relevant sources are located by:','["skimming randomly", "flipping pages", "guessing", "using keywords, databases and indexes"]'::jsonb,3,'Search tools find relevant material.','original'),
('128.34.c.13.E',3,'Which is a relevant source for a report on solar energy?','["a government energy report", "a game manual", "a menu", "a cartoon"]'::jsonb,0,'Relevant sources address the topic.','original'),
('128.34.c.13.F',3,'Synthesizing means:','["copying one source", "combining information from sources to form a new understanding", "skipping sources", "listing titles"]'::jsonb,1,'Synthesis builds insight.','original'),
('128.34.c.13.G.i',4,'A credible source is usually written by:','["an anonymous poster", "a friend only", "an expert and supported by evidence", "an advertiser"]'::jsonb,2,'Expertise and evidence matter.','original'),
('128.34.c.13.G.i',4,'Bias by omission occurs when a source:','["gives context", "cites experts", "lists all facts", "leaves out important facts that would change the picture"]'::jsonb,3,'What is omitted can mislead.','original'),
('128.34.c.13.G.ii',4,'An ad hominem fallacy attacks:','["the person instead of the argument", "the data", "the topic", "the evidence"]'::jsonb,0,'It targets the speaker.','original'),
('128.34.c.13.G.ii',4,'A slippery slope fallacy claims that:','["data is accurate", "one small step will inevitably lead to extreme consequences", "every step is safe", "a trend is stable"]'::jsonb,1,'It exaggerates a chain of events.','original'),
('128.34.c.13.H',3,'A citation for a paraphrased idea should:','["be invented", "be a joke", "credit the source of the idea", "be left out"]'::jsonb,2,'Paraphrased ideas still need credit.','original'),
('128.34.c.13.H',3,'Quotation marks are used when a writer:','["restates ideas fully", "makes an outline", "summarizes broadly", "includes an author''s exact words"]'::jsonb,3,'Exact words are quoted and cited.','original'),
('128.34.c.13.I',2,'Digital technology can help research by:','["allowing quick searches and note-sharing", "preventing citing", "removing sources", "replacing thinking"]'::jsonb,0,'Technology supports research when used wisely.','original'),
('128.34.c.13.I',2,'A learner may incorporate digital technology by:','["avoiding computers", "creating a slideshow to present findings", "printing nothing", "hiding notes"]'::jsonb,1,'Digital tools enhance presentation.','original'),
('128.34.c.13.J',3,'A research presentation using images, text and narration is:','["silent", "only oral", "multimodal", "only written"]'::jsonb,2,'It blends modes.','original'),
('128.34.c.13.J',3,'A pictorial mode of delivery is:','["a spoken speech", "a letter", "a phone call", "an infographic or poster"]'::jsonb,3,'Pictorial means visual.','original'),
('128.34.c.2.A',3,'Applying phonetic knowledge helps English learners to:','["pronounce and spell unfamiliar words", "guess meanings only", "skip vowels", "avoid reading"]'::jsonb,0,'Phonics supports decoding and spelling.','original'),
('128.34.c.2.A',3,'Which pair of words rhymes?','["cough and bough", "though and slow", "though and tough", "through and thought"]'::jsonb,1,'Though and slow share the same vowel sound.','original'),
('128.34.c.2.B',2,'Writing answers legibly helps because:','["it hides mistakes", "it removes ideas", "readers can understand the response", "it takes longer"]'::jsonb,2,'Legibility supports communication.','original'),
('128.34.c.2.B',2,'A complete thought in English contains:','["only a conjunction", "only an adjective", "only a noun", "a subject and a predicate"]'::jsonb,3,'Complete sentences have both parts.','original'),
('128.34.c.3.A',3,'A glossary in a textbook is used to:','["look up the meaning of key terms", "list the authors", "show the title", "number the pages"]'::jsonb,0,'Glossaries define terms.','original'),
('128.34.c.3.A',3,'A technical dictionary would be most helpful for understanding:','["a love poem", "specialized words in a science or trade field", "a greeting", "a joke"]'::jsonb,1,'Technical dictionaries cover field-specific terms.','original'),
('128.34.c.3.B',4,'Denotation is a word''s:','["number of syllables", "emotional associations", "dictionary meaning", "rhyming sound"]'::jsonb,2,'Denotation is literal meaning.','original'),
('128.34.c.3.B',4,'The word ''home'' has a connotation of:','["a measurement", "a legal term", "a building address", "warmth and comfort"]'::jsonb,3,'Connotation includes feelings.','original'),
('128.34.c.3.C',3,'The phrase ''bona fide'' used in English means:','["genuine", "fast", "fake", "funny"]'::jsonb,0,'Bona fide is Latin for in good faith.','original'),
('128.34.c.3.C',3,'The phrase ''et cetera'' means:','["and how", "and other things", "and why", "and then"]'::jsonb,1,'Etc. is Latin for and the rest.','original'),
('128.34.c.3.E',3,'The word ''bank'' can mean a river edge or a place for money. This is a:','["prefix", "antonym", "multiple-meaning word", "synonym"]'::jsonb,2,'One spelling, several meanings.','original'),
('128.34.c.3.F',3,'The idiom ''break the ice'' means:','["cook dinner", "cause trouble", "smash frozen water", "start a conversation in a social setting"]'::jsonb,3,'Idioms have figurative meanings.','original'),
('128.34.c.3.F',3,'Synonyms are words that:','["have similar meanings", "have opposite meanings", "look the same", "sound the same"]'::jsonb,0,'Synonyms share meaning.','original'),
('128.34.c.4',2,'Reading, writing, speaking and listening in English:','["never connect", "develop together and strengthen each other", "develop separately", "are unimportant"]'::jsonb,1,'Language skills support one another.','original'),
('128.34.c.4',2,'Listening to English podcasts can help a learner build:','["only handwriting", "only math", "vocabulary and comprehension", "no skills"]'::jsonb,2,'Listening grows language.','original'),
('128.34.c.5',2,'A student listens to a talk, takes notes and writes a summary. This integrates:','["silence", "drawing", "math", "listening and writing"]'::jsonb,3,'Skills work together.','original'),
('128.34.c.5',2,'Reading an article and discussing it integrates:','["reading, speaking and listening", "no skills", "only math", "only drawing"]'::jsonb,0,'Language skills combine.','original'),
('128.34.c.6.A',3,'A learner reads a manual to assemble a desk. The purpose for reading is to:','["learn a legend", "follow the steps accurately", "enjoy a poem", "find a rhyme"]'::jsonb,1,'Purpose guides reading.','original'),
('128.34.c.6.A',3,'Setting a purpose for self-selected reading might be:','["to count pages", "to guess", "to enjoy a story or learn about a hobby", "to avoid thinking"]'::jsonb,2,'Self-selected reading is often for interest.','original'),
('128.34.c.6.B',3,'Generating questions before reading helps a reader to:','["skip headings", "avoid reading", "forget the topic", "activate prior knowledge and set a purpose"]'::jsonb,3,'Questions prepare the mind.','original'),
('128.34.c.6.C',3,'A reader predicts what a chapter will cover after reading its heading. The reader is using:','["text features", "guesses", "rhyme", "dialogue only"]'::jsonb,0,'Headings are text features.','original'),
('128.34.c.6.C',3,'A prediction is confirmed when:','["the font changes", "later text matches the prediction", "the title changes", "the page turns"]'::jsonb,1,'Evidence confirms predictions.','original'),
('128.34.c.6.D',3,'Creating a mental image while reading helps a learner:','["avoid meaning", "ignore setting", "understand descriptions and details", "skip paragraphs"]'::jsonb,2,'Visualizing supports comprehension.','original'),
('128.34.c.6.D',3,'Which phrase supports a strong mental image?','["something happened", "it was a place", "a thing there", "rain hammering on the metal roof"]'::jsonb,3,'Sensory language creates images.','original'),
('128.34.c.6.E',3,'Relating a story about immigration to your own family''s journey is a connection to:','["personal experience", "the index", "the glossary", "the font"]'::jsonb,0,'Personal connections relate text to life.','original'),
('128.34.c.6.E',3,'Linking a novel to a news report on the same issue is a connection to:','["page numbers", "society", "the font", "the cover"]'::jsonb,1,'Text-to-world connection.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_10_v1'
from (values
('128.34.c.6.F',3,'''Lucas kept checking his phone and sighed.'' A reader may infer Lucas is:','["asleep", "laughing", "waiting for important news", "bored with life"]'::jsonb,2,'Actions suggest anticipation.','original'),
('128.34.c.6.F',3,'An inference should be supported by:','["a random detail", "the cover", "a guess", "evidence from the text"]'::jsonb,3,'Inferences need textual support.','original'),
('128.34.c.6.G',3,'Participating in a discussion about a text helps a learner to:','["evaluate key details with others", "avoid thinking", "stay silent", "skip the text"]'::jsonb,0,'Discussion deepens understanding.','original'),
('128.34.c.6.G',3,'Which contribution moves a text discussion forward?','["I didn''t read it.", "On page 12, the author says the town was afraid, which supports our idea.", "Pass.", "Whatever."]'::jsonb,1,'Citing the text supports ideas.','original'),
('128.34.c.6.H',3,'Synthesizing two texts produces:','["a list of authors", "a copy of one text", "new understanding that neither text gives alone", "a title"]'::jsonb,2,'Synthesis builds insight.','original'),
('128.34.c.6.H',3,'Which task requires synthesizing two texts?','["counting words", "copying a poem", "listing titles", "explaining a theme found in both a poem and an essay"]'::jsonb,3,'It merges texts.','original'),
('128.34.c.6.I',3,'When comprehension breaks down, a reader can:','["reread, use background knowledge or ask for help", "stop reading", "skip it", "guess blindly"]'::jsonb,0,'Fix-up strategies restore meaning.','original'),
('128.34.c.7.A',2,'A personal connection response might begin with:','["The font is serif.", "This story reminds me of when I moved to a new school.", "Chapter 2 is long.", "Page 4 is blank."]'::jsonb,1,'Personal connections link to life.','original'),
('128.34.c.7.A',2,'Self-selected texts are books or articles that a reader:','["must read for a test", "cannot understand", "chooses for personal interest", "never opens"]'::jsonb,2,'Self-selected means chosen.','original'),
('128.34.c.7.B',3,'A response comparing two texts in a set should:','["copy one text", "omit evidence", "list titles only", "show similarities and differences with details"]'::jsonb,3,'Comparisons need evidence.','original'),
('128.34.c.7.B',3,'A response that demonstrates understanding includes:','["specific details and explanation", "only an opinion", "only a title", "only a guess"]'::jsonb,0,'Understanding is shown with details.','original'),
('128.34.c.7.C',3,'Original commentary in a response means the writer:','["copies a paragraph", "explains the meaning of the evidence in their own words", "summarizes without analysis", "only quotes"]'::jsonb,1,'Commentary connects evidence to the claim.','original'),
('128.34.c.7.C',3,'A comprehensive response uses text evidence and:','["random facts", "more quotations only", "original commentary that explains it", "no analysis"]'::jsonb,2,'Evidence needs explanation.','original'),
('128.34.c.7.D',3,'A good summary keeps:','["every detail", "the writer''s opinions", "new ideas", "main ideas in logical order"]'::jsonb,3,'Summaries are concise.','original'),
('128.34.c.7.D',3,'Paraphrasing a sentence means:','["restating it in new words with the same meaning", "copying it", "deleting it", "reversing it"]'::jsonb,0,'Paraphrase keeps meaning.','original'),
('128.34.c.7.E',3,'Labeling and annotating a diagram helps a reader to:','["erase the diagram", "identify parts and record thinking", "skip the text", "hide information"]'::jsonb,1,'Annotation supports understanding.','original'),
('128.34.c.7.E',3,'A reading log is a way to:','["hide notes", "grade the author", "record thoughts about a text", "skip reading"]'::jsonb,2,'Logs capture responses.','original'),
('128.34.c.7.F',3,'Using academic vocabulary such as ''analyze'' in a response shows:','["confusion", "avoidance", "copying", "application of newly learned language"]'::jsonb,3,'Academic vocabulary strengthens writing.','original'),
('128.34.c.7.G',3,'An implicit meaning is:','["suggested and needs to be inferred", "written word for word", "printed in bold", "listed in the glossary"]'::jsonb,0,'Implicit means implied.','original'),
('128.34.c.7.H',3,'A formal essay requires an academic:','["text-message style", "register and objective tone", "spoken style", "slang style"]'::jsonb,1,'Register fits the setting.','original'),
('128.34.c.7.H',3,'Voice and tone in a response should fit:','["only the writer''s mood", "the font", "the audience and purpose", "the paper"]'::jsonb,2,'Style should suit the context.','original'),
('128.34.c.7.I',3,'A thoughtful reader changes an earlier response when:','["a page turns", "a classmate disagrees only", "the bell rings", "valid evidence shows a better interpretation"]'::jsonb,3,'Evidence warrants revision.','original'),
('128.34.c.7.J',4,'To challenge an author''s claim, a student should:','["use relevant text evidence to show a flaw", "insult the author", "ignore the text", "guess"]'::jsonb,0,'Challenges rely on evidence.','original'),
('128.34.c.7.J',4,'To defend an author''s claim, a student can:','["avoid the text", "cite passages that support the claim", "repeat it only", "change the topic"]'::jsonb,1,'Defenses use evidence.','original'),
('128.34.c.7.K',2,'A beginning English learner can express an opinion using:','["only silence", "only translations", "short phrases such as ''I like this'' or ''I disagree''", "only long essays"]'::jsonb,2,'Early expression uses simple language.','original'),
('128.34.c.7.K',2,'As language skills grow, a learner moves from single words to:','["fewer words", "silence", "only gestures", "complete sentences and extended responses"]'::jsonb,3,'Communication expands with proficiency.','original'),
('128.34.c.8.A',4,'A theme is developed through characterization and plot when:','["characters'' choices and events repeatedly show an idea", "the setting is named", "the title appears", "the author is listed"]'::jsonb,0,'Themes emerge from character and plot.','original'),
('128.34.c.8.A',4,'Which statement is a theme?','["The story is set in Texas.", "Perseverance can overcome obstacles.", "There is a school.", "Ana is a student."]'::jsonb,1,'A theme is a universal message.','original'),
('128.34.c.8.B',4,'A complex yet believable character:','["is perfect", "has no motives", "has both strengths and flaws that feel real", "never changes"]'::jsonb,2,'Complexity makes characters believable.','original'),
('128.34.c.8.B',4,'An author develops a character through:','["indexes", "page numbers", "fonts", "actions, dialogue, thoughts and other characters'' reactions"]'::jsonb,3,'These methods build characterization.','original'),
('128.34.c.8.C',4,'A flashback is:','["a scene that returns to an earlier time", "a footnote", "the title", "the ending"]'::jsonb,0,'Flashbacks interrupt chronological order.','original'),
('128.34.c.8.C',4,'Foreshadowing is:','["a conclusion", "a hint about what will happen later", "a summary", "a citation"]'::jsonb,1,'Foreshadowing builds anticipation.','original'),
('128.34.c.8.D',4,'A setting of poverty and hardship may influence the theme by:','["ending the plot", "erasing characters", "highlighting struggle and perseverance", "removing conflict"]'::jsonb,2,'Setting shapes meaning.','original'),
('128.34.c.8.D',4,'Which shows setting influencing theme?','["A story mentions a street.", "A story uses a title.", "A story has a cover.", "A story in a war zone emphasizes the cost of conflict."]'::jsonb,3,'The setting supports the theme.','original'),
('128.34.c.9.A',3,'Reading American, British and world literature helps students:','["understand different cultures and perspectives", "avoid books", "skip authors", "forget history"]'::jsonb,0,'Literature broadens understanding.','original'),
('128.34.c.9.A',3,'Which is an example of world literature?','["a manual", "a novel translated from another language", "a bus schedule", "a menu"]'::jsonb,1,'World literature crosses borders.','original'),
('128.34.c.9.B',4,'Prosody refers to:','["the glossary", "the table of contents", "the rhythm and sound patterns of poetry", "the page number"]'::jsonb,2,'Prosody concerns meter and sound.','original'),
('128.34.c.9.B',4,'Line length in a poem can:','["change the title", "end the poem", "delete meaning", "affect pacing and emphasis"]'::jsonb,3,'Line breaks shape reading.','original'),
('128.34.c.9.C',4,'A soliloquy is:','["a speech in which a character voices private thoughts alone on stage", "a conversation between two characters", "a prop list", "a stage direction"]'::jsonb,0,'Soliloquies reveal inner thoughts.','original'),
('128.34.c.9.C',4,'An aside in a play is:','["a loud argument", "a remark spoken to the audience that other characters do not hear", "a list of cast", "a scene title"]'::jsonb,1,'Asides share private commentary.','original'),
('128.34.c.9.D.i',3,'A strong thesis is supported by:','["guesses", "jokes", "relevant evidence and pertinent examples", "unrelated facts"]'::jsonb,2,'Evidence supports the thesis.','original'),
('128.34.c.9.D.i',3,'A clear thesis states:','["the author''s name", "the page count", "the date", "the main point of the essay"]'::jsonb,3,'The thesis controls the essay.','original'),
('128.34.c.9.D.ii',3,'A table or graph in an article helps the reader to:','["see data organized visually", "skip the text", "find rhymes", "count syllables"]'::jsonb,0,'Graphic features display information.','original'),
('128.34.c.9.D.ii',3,'Bullets and numbered lists in a manual:','["confuse readers", "make steps and items easy to follow", "replace headings", "hide the steps"]'::jsonb,1,'Lists organize.','original'),
('128.34.c.9.D.iii',3,'A text that uses both chronological order and compare-and-contrast develops its thesis through:','["random order", "one pattern only", "multiple organizational patterns", "no pattern"]'::jsonb,2,'Texts can combine patterns.','original'),
('128.34.c.9.D.iii',3,'Organizing patterns help readers because they:','["lengthen text", "remove details", "hide the thesis", "make ideas easier to follow"]'::jsonb,3,'Patterns create clarity.','original'),
('128.34.c.9.E.i',3,'A clear arguable claim is one that:','["can be supported or challenged", "is a title", "is a proven fact", "is a question"]'::jsonb,0,'A claim takes a debatable position.','original'),
('128.34.c.9.E.i',3,'An appeal to logic uses:','["only feelings", "facts, reasons and evidence", "only repetition", "only the writer''s fame"]'::jsonb,1,'Logos relies on reasoning.','original'),
('128.34.c.9.E.ii',4,'A concession in an argument is when the writer:','["ignores the opposition", "denies everything", "admits that an opposing point has some validity", "changes the topic"]'::jsonb,2,'Concessions acknowledge the other side.','original'),
('128.34.c.9.E.ii',4,'A rebuttal is:','["a footnote", "a quotation", "a title", "a response that counters an opposing argument"]'::jsonb,3,'Rebuttals answer the counterargument.','original'),
('128.34.c.9.E.iii',3,'A brochure on teen driving safety is aimed at:','["teenagers and their parents", "retirees only", "pets", "toddlers"]'::jsonb,0,'Content signals audience.','original'),
('128.34.c.9.E.iii',3,'An identifiable audience for an editorial in a school newspaper is:','["only the editor", "students, teachers and parents", "no one", "only a company"]'::jsonb,1,'Editorials address a community.','original'),
('128.34.c.9.F',3,'A digital text may include features like:','["paper pages", "stage props", "hyperlinks and embedded media", "handwriting"]'::jsonb,2,'Digital features add interactivity.','original'),
('128.34.c.10.C',3,'A bold subheading in a report helps readers to:','["hide the thesis", "change the topic", "skip the content", "find sections quickly"]'::jsonb,3,'Headings organize.','original'),
('128.34.c.10.C',3,'A diagram with labels in a science chapter is meant to:','["show parts of a system clearly", "list sources", "entertain with jokes", "replace paragraphs"]'::jsonb,0,'Graphic features clarify.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_10_v1'
from (values
('128.34.c.11.D.i',3,'A controlled sentence variety can be achieved by mixing:','["only commands", "simple, compound and complex sentences", "only fragments", "only questions"]'::jsonb,1,'Variety improves writing.','original'),
('128.34.c.11.D.ii',3,'A writer chooses the active voice to:','["lengthen the sentence", "hide the actor", "make the actor clear and the sentence direct", "remove verbs"]'::jsonb,2,'Active voice is clearer.','original'),
('128.34.c.11.D.ii',3,'Which verb tense shows an action that will happen?','["past", "past perfect", "present perfect", "future"]'::jsonb,3,'Future tense refers to later time.','original'),
('128.34.c.11.D.iii',3,'Choose the correct form: ''The team of players ___ practicing.''','["is", "are", "were", "am"]'::jsonb,0,'Team is a singular collective noun.','original'),
('128.34.c.11.D.iii',3,'Which sentence has correct agreement?','["Each of the answers be correct.", "Each of the answers is correct.", "Each of the answers are correct.", "Each of the answers were correct."]'::jsonb,1,'Each is singular.','original'),
('128.34.c.11.D.ix',3,'Which abbreviation is standard for ''Street'' in an address?','["Sr.", "Sttt", "St.", "Str"]'::jsonb,2,'St. is the standard abbreviation.','original'),
('128.34.c.11.D.v',3,'Which phrase shows singular possession correctly?','["the teacher desk''s", "the teachers'' desk''s", "the teachers desk", "the teacher''s desk"]'::jsonb,3,'Singular nouns add ''s.','original'),
('128.34.c.11.D.v',3,'Which uses an apostrophe in a contraction correctly?','["They''re going to the library.", "Theyre going to the library.", "They''er going to the library.", "Their going to the library."]'::jsonb,0,'They''re means they are.','original'),
('128.34.c.11.D.viii',3,'A comma is used after an introductory phrase in:','["After the meeting we, left.", "After the meeting, we left.", "After the meeting we left,.", "After, the meeting we left."]'::jsonb,1,'Place a comma after an introductory phrase.','original'),
('128.34.c.13.F',3,'Synthesizing a survey and an interview involves:','["listing questions", "copying the interview", "combining their findings into one conclusion", "ignoring the survey"]'::jsonb,2,'Synthesis merges findings.','original'),
('128.34.c.13.F',3,'A researcher who connects findings from three articles into one explanation is:','["guessing", "skimming", "copying", "synthesizing"]'::jsonb,3,'Synthesis builds new understanding.','original'),
('128.34.c.3.E',3,'Which word is a homograph of ''tear'' (to rip)?','["tear (a drop from the eye)", "tier", "teer", "tire"]'::jsonb,0,'Homographs share spelling.','original'),
('128.34.c.3.E',3,'A learner mixes up ''then'' and ''than''. These are:','["antonyms", "commonly confused terms", "prefixes", "synonyms"]'::jsonb,1,'They look and sound similar but differ in use.','original'),
('128.34.c.6.B',3,'After reading, a learner asks ''What is the author''s main argument?'' This question:','["wastes time", "repeats the title", "deepens understanding of the text", "avoids meaning"]'::jsonb,2,'Reflective questions strengthen comprehension.','original'),
('128.34.c.6.B',3,'Answering questions about a text before reading can help a learner to:','["skip the headings", "avoid the text", "forget the topic", "build background knowledge"]'::jsonb,3,'Prereading questions prepare readers.','original'),
('128.34.c.6.I',3,'A learner who loses the thread of a long paragraph can:','["reread slowly and paraphrase each sentence", "give up", "guess", "skip it"]'::jsonb,0,'Rereading and paraphrasing restore meaning.','original'),
('128.34.c.6.I',3,'Using a bilingual dictionary to understand a key word is a:','["citation", "comprehension adjustment", "prediction", "distraction"]'::jsonb,1,'It is a fix-up strategy.','original'),
('128.34.c.7.F',3,'Which choice uses academic vocabulary appropriately?','["The narrator''s whatever.", "Things happen in it.", "The narrator''s perspective influences how we interpret events.", "The narrator did stuff."]'::jsonb,2,'Academic terms add precision.','original'),
('128.34.c.7.F',3,'Using content vocabulary from science class in a lab report shows:','["avoidance", "copying", "confusion", "understanding of the subject"]'::jsonb,3,'Content words signal learning.','original'),
('128.34.c.7.G',3,'A reader discusses what a character''s silence suggests. This explores:','["implicit meaning", "print features", "page numbers", "glossary terms"]'::jsonb,0,'Silence hints at feelings.','original'),
('128.34.c.7.G',3,'Explicit meaning can be located by:','["guessing", "finding the sentence that states it directly", "reading the title only", "skipping lines"]'::jsonb,1,'Explicit ideas are stated.','original'),
('128.34.c.7.I',3,'A student''s first interpretation changes after a later chapter. The student should:','["delete the book", "repeat the old idea", "revise the response using the new evidence", "ignore the chapter"]'::jsonb,2,'Evidence guides revision.','original'),
('128.34.c.7.I',3,'Adjusting a response when valid evidence warrants shows:','["stubbornness", "carelessness", "weak effort", "careful, flexible thinking"]'::jsonb,3,'Good readers adjust.','original'),
('128.34.c.9.F',3,'A podcast with a transcript and images is multimodal because it:','["uses sound, text and visuals", "uses one mode", "has no content", "has only words"]'::jsonb,0,'Multiple modes work together.','original'),
('128.34.c.9.F',3,'A website with video and clickable links is an example of:','["a printed book", "a digital text", "a stage script", "a poem only"]'::jsonb,1,'Digital texts use online features.','original'),
('128.34.c.3.D',2,'An English learner needs a word for where a book is placed on a shelf. Which word fits?','["finally", "courageous", "adjacent", "amazingly"]'::jsonb,2,'Adjacent tells position.','original'),
('128.34.c.3.D',2,'Which word tells the order of steps in a lab procedure?','["carefully", "enormous", "underneath", "subsequently"]'::jsonb,3,'It signals what comes next.','original'),
('128.34.c.3.D',2,'A classmate gives directions to the library. Which word tells a direction?','["westward", "quickly", "delightful", "argue"]'::jsonb,0,'Westward is a direction word.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
